description:
Design a binary priority decoder that identifies the highest priority active input from a set of inputs, where the priority is determined by a set of priority bits. The module has n input signals, and based on the given priority bits, it generates a one-hot output indicating which input has the highest priority. The decoder employs bitwise operations to encode the priorities, sort them, and create a masked signal that only activates the highest priority input. The output is guaranteed to be a valid one-hot encoded value, ensuring that only one output line is asserted at any time.
module top_module(
  input [n-1:0] in,
  input [n-1:0] priority_bits,
  output out
);

code:
module top_module(
  input [n-1:0] in,
  input [n-1:0] priority_bits,
  output out
);parameter n = 4; // number of binary signals

wire [n-1:0] priority_encoded;
wire [n-1:0] priority_sorted;
wire [n-1:0] priority_mask;
wire [n-1:0] priority_masked;

assign priority_encoded = ~(in ^ priority_bits);
assign priority_sorted = {priority_encoded[n-1], priority_encoded[n-2:0]};
assign priority_mask = {priority_sorted[n-1] & priority_sorted[n-2:0], priority_sorted[n-2] & priority_sorted[n-3:0], priority_sorted[n-3] & priority_sorted[n-4:0], priority_sorted[n-4]};
assign priority_masked = priority_encoded & priority_mask;

assign out = $onehot0(priority_masked);

endmodule

