module pedestrian_crossing (
        input clk,
        input areset,
        input timer_done,
        output reg signal);parameter Walk=1'b1, Dont_Walk=1'b0;
	reg state;
	always @(posedge clk or posedge areset) begin
		if (areset)
			state <= Dont_Walk;
		else begin
			case (state)
				Walk: state <= timer_done ? Dont_Walk : Walk;
				Dont_Walk: state <= timer_done ? Walk : Dont_Walk;
			endcase
		end
	end

	assign signal = (state == Walk);

endmodule

