description:
Design a circuit that converts a 6-bit binary input into a Binary-Coded Decimal (BCD) representation. The module takes a 6-bit binary value and outputs two 4-bit BCD digits. It employs a double-dabble algorithm to successively shift the binary input while adjusting the BCD digits to ensure valid BCD encoding by adding a bias when the BCD digits exceed the maximum value of 4. The two outputs, bcd0 and bcd1, represent the tens and units digits of the BCD equivalent, respectively.
module top_module(
    input [5:0] bin_val,
    output [3:0] bcd0, bcd1 
    );

code:
module top_module(
    input [5:0] bin_val,
    output [3:0] bcd0, bcd1 
    );integer i;
    reg [7:0] bcd;

    always @(bin_val)
    begin
        bcd = 0;
        for (i = 0; i < 6; i = i + 1) 
        begin
            bcd = {bcd[6:0], bin_val[5-i]};
            if (i < 5 && bcd[3:0] > 4)
                bcd[3:0] = bcd[3:0] + 3;
            if (i < 5 && bcd[7:4] > 4)
                bcd[7:4] = bcd[7:4] + 3; 
        end
    end

    assign bcd0 = bcd[7:4];
    assign bcd0 = bcd[3:0];

endmodule

