module fsm (
    input clk,
    input reset,
    input x,
    output reg y);

    parameter A=0, B=1, C=2, D=3;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= A;
        else state <= next;
    end

    always_comb begin
        case (state)
            A: next = x ? B : A;
            B: next = x ? B : C;
            C: next = x ? B : D;
            D: next = x ? B : A;
            default: next = 'x;
        endcase
    end

    assign y = (state == D);

endmodule

