			if( div_cnt==cambio0 ) ym_pm <= 1'b0; 
			div_cnt <= div_cnt + 1'b1;
		end
	end
end

reg ultpm;

always @(posedge clk or posedge rst) begin : pm_counter_ff
	if( rst )  begin
		pm_counter <= 32'd0;
		ultpm      <= 1'b0;
	end
	else begin
		ultpm <= ym_pm;
		if(rst_counter) 
			pm_counter <= 32'd0;
		else
			if( irq_n && ym_pm && !ultpm ) 
				pm_counter <= pm_counter + 1'd1;		
	end
end

