module state_module (
        input clk,
        input reset,
        input j,
        output reg z);parameter K=0, L=1, M=2, N=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= K;
		else 
			state <= next;

	always_comb begin
		case(state)
			K: next = j ? M : L;
			L: next = j ? K : N;
			M: next = j ? N : K;
			N: next = j ? M : L;
			default: next = 'x;
		endcase
	end

	assign z = (state == K || state == M);

endmodule

