module top_module(
    input  clock_50_MHz,
    input  reset_n,
    output clock_1_49_Hz
);reg [24:0] counter;

    always @ (posedge clock_50_MHz or negedge reset_n)
    begin
        if (! reset_n)
            counter <= 0;
        else
            counter <= counter + 1;
    end

    assign clock_1_49_Hz = counter [24];endmodule

