Design a gated D latch that captures the value of input D on the rising edge of the clock (CLK) when the enable signal (G) is high. The output Q reflects the stored value from D as long as G is asserted, allowing for controlled data storage based on the clock signal.
module top_module(
  input D, G, CLK,
  output Q
);

code:
module top_module(
  input D, G, CLK,
  output Q
);reg Q_int;

  always @(posedge CLK) begin
    if (G) begin
      Q_int <= D;
    end
  end

  assign Q = Q_int;

endmodule

