module top_module(
		clk, clrn, shift, datain,
		dataout );parameter DATA_WIDTH=8;

	input clk;
	input clrn;
	input shift;
	input datain;
	output [DATA_WIDTH-1:0] dataout;	

	reg [DATA_WIDTH-1:0] temp;

	always @ (posedge clk or negedge clrn) begin
	  if(!clrn)
		  temp<={DATA_WIDTH{1'b0}};
	  else begin
		  if(shift)
            temp<={datain, temp[DATA_WIDTH-1:1]};
