  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      fifo_head <= 6'h0;
      fifo_tail <= 6'h0;
      fifo_count <= 6'h0;
      fifo_EF <= 1'b1;
      rfifo_full <= 1'b0;
      fifo_rdata <= 8'h0;
      rfifo_used <= 6'h0; // Initialize rfifo_used
    end else begin
      if (fifo_rd && ~fifo_EF) begin
        fifo_rdata <= fifo_data[fifo_tail];
        fifo_tail <= fifo_tail + 1;
        fifo_count <= fifo_count - 1;
        if (fifo_count == 6'h1) begin
          fifo_EF <= 1'b1;
        end
        rfifo_used <= rfifo_used - 1;
        rfifo_full <= 1'b0;
      end else begin
        fifo_rdata <= 8'h0;
      end

      if (~fifo_rd && ~rfifo_full) begin
        fifo_data[fifo_head] <= 8'h1; // Corrected to write valid data (dummy data)
        fifo_head <= fifo_head + 1;
        fifo_count <= fifo_count + 1;
        if (fifo_count == 6'h3F) begin // Change from 6'h40 to 6'h3F
          rfifo_full <= 1'b1;
        end else begin
          rfifo_full <= 1'b0; // Change to update rfifo_full state correctly
        end
        fifo_EF <= 1'b0;
        rfifo_used <= rfifo_used + 1;
      end
    end
  end

endmodule

